import{_ as s,h as r,i as e,c as i,v as t,p as n,x as l,m as c,e as p,S as d}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"梯度裁剪与损失尖峰","description":"","frontmatter":{"title":"梯度裁剪与损失尖峰","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grad-clip-loss-spike.md","filePath":"llm/grad-clip-loss-spike.md","lastUpdated":1788454257000}'),h={name:"llm/grad-clip-loss-spike.md"};function E(m,a,A,b,B,_){const o=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="梯度裁剪与损失尖峰" tabindex="-1">梯度裁剪与损失尖峰 <a class="header-anchor" href="#梯度裁剪与损失尖峰" aria-label="Permalink to &quot;梯度裁剪与损失尖峰&quot;">​</a></h1><div class="epigraph"><p>范数裁剪把一次过大的更新按比例缩回球内；它挡住爆炸，但不解释损失为何突然竖起一条尖刺。</p><footer>—— 裁剪的 RNN 前史见 Pascanu 等；大模型训练中的尖峰见 PaLM 等报告</footer></div><p>预训练曲线很少是光滑的指数下降。每隔一段 token，训练损失会突然跳高一截，再在随后若干步里掉回来，或者掉不回来、变成一条更高的平台。伴随而来的是梯度全局范数的尖刺。几乎所有大模型配方都做全局梯度裁剪：若 \\(\\|\\mathbf{g}\\|_2&gt;c\\)，就把梯度乘 \\(c/\\|\\mathbf{g}\\|_2\\)。\\(c=1.0\\) 是常见默认值。裁剪是保险，不是诊断。本篇把裁剪的几何说清楚，再把损失尖峰的常见来源与工程应对分开：哪些是坏 batch，哪些是优化器与精度，哪些是结构上的饱和。不把某一篇博客里的「跳过一个 batch 就好了」写成普遍定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深层网络的梯度可以沿层连乘。即令 Pre-LN 给了残差一条公路，注意力 softmax、FFN 的激活、嵌入表的巨大学习率，仍能在个别 token 上制造极大的局部梯度。数据侧更直接：一段有毒、重复、编码损坏、或极长的特殊序列，损失本身可以比均值高一个数量级。若不限制更新幅度，Adam 的一步会把权重打到不可恢复的区域：LayerNorm 的方差崩掉、logits 溢出、此后每步都在 NaN 边缘。</p><p>尖峰与爆炸相邻但不是同一件事。爆炸是范数失控、下一步就 NaN；尖峰是损失突然变差，范数可能仍被裁剪钉在 \\(c\\) 上。你在日志里看到的是「grad norm 贴着 clip 阈值、loss 竖起来」。问题于是有两层：如何避免单步更新毁掉权重；如何判断这次尖峰是可恢复的噪声，还是优化已经离开了可工作的盆地。</p><h3 id="全局范数裁剪在做什么" tabindex="-1">全局范数裁剪在做什么 <a class="header-anchor" href="#全局范数裁剪在做什么" aria-label="Permalink to &quot;全局范数裁剪在做什么&quot;">​</a></h3><p>记全体可训练参数的梯度拼成向量 \\(\\mathbf{g}\\)。全局 \\(\\ell_2\\) 裁剪是</p> \\[\\mathbf{g}\\leftarrow \\mathbf{g}\\cdot \\min\\bigl(1,\\, c/\\|\\mathbf{g}\\|_2\\bigr). \\]<p>它保方向，改幅度。被裁剪时，有效学习率变成 \\(\\eta\\cdot c/\\|\\mathbf{g}\\|\\)，对这一步的所有参数一视同仁。这和 Adam 的每坐标缩放正交：先按 Adam 做出预条件后的方向（实现上裁剪通常加在反传之后、Adam 之前，顺序以代码为准），再把整包梯度推进半径 \\(c\\) 的球。顺序若颠倒——先 Adam 再按更新向量裁——统计对象变了，复现别人的 \\(c\\) 会失败。</p><p><span class="marginnote">「梯度范数」必须定义在哪一组参数上。有的实现不含嵌入，有的把流水线各段的局部范数平方后再开方。ZeRO-3 下参数分片，必须跨 rank 做一次范数 All-Reduce 才能得到全局 \\(c\\)。配置里写 clip=1.0 却在分片上各自裁，等于把阈值悄悄放大了 \\(\\sqrt{N}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准配方：反传得到梯度，跨数据并行组 All-Reduce（或 ZeRO 的 Reduce-Scatter），算全局范数，裁剪，再进优化器。日志同时记下未裁剪范数、裁剪触发比例、以及这一 step 的损失。触发比例长期接近 100%，说明 \\(c\\) 相对当前学习率过紧，模型几乎每步都在用缩小的有效 \\(\\eta\\) 训练，日程表上的峰值是假的。触发比例接近 0，裁剪形同关闭。健康区间没有统一数字，但「从几乎不触发突然变成步步触发」是尖峰的伴随症状。</p><p>应对尖峰的工程菜单通常叠几层，而不是只靠 \\(c\\)：</p><ol><li><strong>裁剪</strong>：限制单步幅度，默认始终开。</li><li><strong>跳过 / 回滚</strong>：若未裁剪范数或损失超过硬阈值，丢弃这一 step 的更新，或从上一个检查点恢复。PaLM 等报告描述过不稳定步。是否回滚、回滚多远，各家不同。</li><li><strong>结构侧</strong>：注意力 logits 的 z-loss（PaLM）、QK 归一化、嵌入与输出头更小的学习率，降低尖峰的发生率，而不是尖峰出现之后再挡。</li><li><strong>数据侧</strong>：过滤极端文档、截断异常长度、检查重复。尖峰若能和某一数据分片对齐，先查数据。</li></ol>',15)),(e(),n(d,null,{default:l(()=>[p(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E4%B8%80%E4%B8%AA%20step%20%E7%9A%84%20batch%22%5D%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%8F%8D%E4%BC%A0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20G%20--%3E%20N%5B%22%E5%85%A8%E5%B1%80%E8%8C%83%E6%95%B0%22%5D%0A%20%20N%20--%3E%20C%7B%22%E8%B6%85%E8%BF%87%20c%3F%22%7D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20O%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%9B%B4%E6%96%B0%22%5D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20K%5B%22%E6%8C%89%E6%AF%94%E4%BE%8B%E8%A3%81%E5%89%AA%22%5D%0A%20%20K%20--%3E%20O%0A%20%20F%20--%3E%20S%7B%22%E6%8D%9F%E5%A4%B1%E5%B0%96%E5%B3%B0%3F%22%7D%0A%20%20S%20--%3E%7C%E5%8F%AF%E6%81%A2%E5%A4%8D%7C%20O%0A%20%20S%20--%3E%7C%E7%A1%AC%E9%98%88%E5%80%BC%7C%20X%5B%22%E8%B7%B3%E8%BF%87%E6%88%96%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="损失尖峰的几种来源" tabindex="-1">损失尖峰的几种来源 <a class="header-anchor" href="#损失尖峰的几种来源" aria-label="Permalink to &quot;损失尖峰的几种来源&quot;">​</a></h3><p>数据尖峰：个别序列损失极高，梯度被这些 token 主导。换一个 batch 就恢复，权重往往没被打坏——前提是裁剪已经把步长挡住。优化尖峰：学习率相对宽度或相对当前损失过高，Adam 的 \\(v\\) 在某些层滞后，连续若干 step 同方向累加。精度尖峰：FP16 下未缩放的小梯度变零、大 logits 溢出，BF16 少见但仍可能在 softmax 前的分数上溢出。结构尖峰：某层注意力极度尖锐，或残差流范数在 Pre-LN 下单调涨，最终在某一层爆发。</p><p>这几类在日志上的差别：数据尖峰与 batch 对齐、换 seed 或换 shard 会挪位置；优化尖峰随学习率与步数移动；精度尖峰伴随 Inf/NaN 计数；结构尖峰在特定层的激活统计上先有征兆。只盯 loss 曲线，四类看起来一样。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>裁剪改变的是这一步的有效 \\(\\eta\\)，不改变损失函数。若尖峰来自真实的大梯度方向（「这个 batch 确实难」），裁剪等于自动减小学习率，下一步仍在附近，损失常常回落——曲线上就是尖刺。若尖峰来自已经损坏的权重（某层 \\(\\gamma\\) 变成极端值、嵌入某一行飞掉），裁剪只是让损坏来得慢一点，损失会在更高的平台上震荡。区分二者要看尖峰之后是否回到原趋势，以及层统计是否复位。</p><p><span class="marginnote">不要把「裁剪触发了所以模型在学习难样本」当成正面叙事。长期 100% 触发意味着你写下的学习率从未真正用上。应下调峰值，或查为何范数系统性偏大，而不是把 \\(c\\) 从 1 改成 0.1 来掩盖。</span></p><h3 id="裁剪救场与跳过-batch" tabindex="-1">裁剪救场与跳过 batch <a class="header-anchor" href="#裁剪救场与跳过-batch" aria-label="Permalink to &quot;裁剪救场与跳过 batch&quot;">​</a></h3><p>跳过一个 step 等于把那个 batch 的梯度当 0。若尖峰是坏数据，这是对的。若尖峰是模型对正常数据的真实高损失，跳过等于从训练集里删掉目前最难的部分，短期曲线变好看，长期可能伤尾部能力。因此硬阈值应极宽，只拦 Inf 和明显损坏；常规波动交给裁剪。回滚更重：它假设最近 \\(k\\) 步的更新是错的，需要可靠检查点。频繁回滚说明配方不稳，不是说明回滚策略成功。</p><p>z-loss 一类辅助项把 logits 的平方和压住，降低「某一位置 logit 极大 → softmax 饱和 → 梯度尖」的链。它减少结构性尖峰，对坏数据无效。QK-norm 同样作用于注意力分数的尺度。这些是改模型，和改 \\(c\\) 不在一层。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>逐层裁剪、按参数组裁剪、自适应梯度裁剪（按权重范数比例裁）改变的是谁与谁比。全局 \\(\\ell_2\\) 是大模型默认，因为它实现简单、跨并行策略好定义。逐层裁剪可以避免「某一层爆炸导致所有层都被缩小」，也可能让本该一起缩小的更新变得不协调。没有普遍赢家。嵌入表单独用更小的 \\(c\\) 或更小的学习率，是常见的分组，因为词表梯度稀疏、偶发极大。</p><p>混合精度与 ZeRO 会让「看到的范数」和「真正的 FP32 范数」不一致。BF16 梯度通信后再在 FP32 主权重上更新时，应在哪一种精度里算 \\(\\|\\mathbf{g}\\|\\)，要在实现里写死。FP8 还多一层缩放因子，范数比较的是缩放后还是缩放前，搞错会让 \\(c\\) 失去意义。</p><p><span class="marginnote">损失尖峰之后若验证损失也台阶式变差，不要只看训练平滑曲线的「已经回来了」。训练损失回来可能是碰到了更容易的后续 shard。下游探针、或固定验证集上的间隔评测，才能判断权重是否被打到另一盆地。</span></p><p>裁剪不能替代合理的学习率日程。WSD 稳定段若峰值过高，裁剪会变成隐性的另一条日程：有效 \\(\\eta\\) 长期低于你以为的常数。分析 token 效率时，应同时画出未裁剪范数与触发比例，否则在比较优化器或并行策略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全局 \\(\\ell_2\\) 裁剪保梯度方向、把幅度钉进半径 \\(c\\) 的球，防止单步毁掉权重。</li><li>损失尖峰有数据、优化、精度、结构四类来源；裁剪是保险，不是分类器。</li><li>长期步步触发说明峰值学习率没用上；跳过 batch 只适合极端损坏，不适合当常规训练。</li><li>范数必须在全局、在约定精度与参数组上计算；ZeRO 分片上的本地裁剪会改写 \\(c\\)。</li><li>z-loss、QK-norm、嵌入分组学习率降低结构性尖峰，与加大裁剪不是同一操作。</li><li>出处：Pascanu 等关于梯度爆炸与裁剪；Chowdhery 等 PaLM 报告中的训练稳定性与 z-loss；后续开源配方中的跳过 / 回滚是工程实践，阈值不可当定理。</li></ul>',16))])}const u=s(h,[["render",E]]);export{f as __pageData,u as default};
